import React from 'react';
import Header from '../header/header';
import { FaCheckCircle, FaStar, FaShieldAlt, FaTools, FaPhoneAlt, FaArrowRight } from 'react-icons/fa';
import FAQ from './FAQ';
import NextSteps from './NextSteps';
import '../../styles/service-page.css';
import Footer from '../footer/footer';
import { SERVICES, BUSINESS } from '../../content';

interface ServicePageProps {
  slug: string;
}

const ServicePage: React.FC<ServicePageProps> = ({ slug }) => {
  const service = SERVICES.find((s) => s.slug === slug);

  if (!service) {
    return (
      <div>
        <Header />
        <div className="container" style={{ padding: '100px 0', textAlign: 'center' }}>
          <h1>Service Not Found</h1>
          <a href="/">Back to Home</a>
        </div>
        <Footer />
      </div>
    );
  }

  return (
    <div className={`service-page ${service.slug}`}>
      <Header />
      
      {/* Service Hero Section */}
      <section className="service-hero">
        <div className="hero-overlay"></div>
        <div className="hero-img-container">
          <img 
            src={service.image} 
            alt={service.imageAlt} 
            className="hero-img"
          />
        </div>
        <div className="container">
          <div className="hero-content">
            <div className="badge">{service.heroBadge}</div>
            <h1 className="hero-title">
              {service.heroTitle} <span className="highlight">{service.heroTitleHighlight}</span>
            </h1>
            <p className="hero-subtitle">
              {service.heroSubtitle}
            </p>
            <div className="hero-actions">
              <a href="#quote" className="btn-primary">Request Free Estimate</a>
              <a href={BUSINESS.phoneHref} className="btn-secondary">
                <FaPhoneAlt /> {BUSINESS.phone}
              </a>
            </div>
            <div className="hero-features">
              {service.heroFeatures.map((feat, index) => (
                <div className="feat-item" key={index}><FaCheckCircle /> {feat}</div>
              ))}
            </div>
          </div>
        </div>
      </section>

      {/* Main Content Body */}
      <section className="service-details">
        <div className="container">
          <div className="details-grid">
            <div className="details-text">
              <h2 className="section-title">{service.detailsTitle}</h2>
              <p>{service.detailsBody}</p>
              <div className="benefit-list">
                {service.benefits.map((benefit, index) => (
                  <div className="benefit" key={index}>
                    <h3>{benefit.title}</h3>
                    <p>{benefit.description}</p>
                  </div>
                ))}
              </div>
            </div>
            <div className="details-cta-card">
              <div className="cta-glass">
                <h3>{service.ctaCardTitle}</h3>
                <p>{service.ctaCardSubtitle}</p>
                <ul className="cta-list">
                  {service.ctaCardBullets.map((bullet, index) => (
                    <li key={index}>
                      {index === 0 ? <FaStar /> : index === 1 ? <FaShieldAlt /> : <FaTools />} {bullet}
                    </li>
                  ))}
                </ul>
                <a href="#quote" className="cta-btn-full">Request Quote <FaArrowRight /></a>
              </div>
            </div>
          </div>
        </div>
      </section>

      <NextSteps />
      
      <FAQ items={service.faqItems} title={service.faqTitle} />

     <Footer/>
    </div>
  );
};

export default ServicePage;
